import { useEffect, useMemo, useState, type FormEvent } from 'react'
import './index.css'

type IconName = 'overview'|'people'|'field'|'learning'|'pathway'|'enterprise'|'support'|'assessment'|'merl'|'reports'|'map'|'messages'|'files'|'admin'|'search'|'bell'|'chevron'|'plus'|'download'|'filter'|'arrow'|'check'|'clock'|'menu'|'close'|'dots'|'calendar'|'shield'|'sync'|'external'|'trend'|'more'
type Section = 'Overview'|'Participants'|'Field operations'|'Learning & cohorts'|'Case management'|'Enterprise & jobs'|'Grants & services'|'Assessments'|'MERL & indicators'|'Reports'|'GIS & coverage'|'Communications'|'Documents'|'Administration'
type Role = 'Program leadership'|'MERL specialist'|'Country coordinator'|'Component manager'|'Field supervisor'|'Enumerator'|'Participant'|'Inclusion specialist'|'Outcomes officer'|'GIS analyst'|'System administrator'|'Partner / donor'
type ParticipantRecord = {id:string;name:string;initials:string;location:string;path:string;stage:string;status:string;gender:string}
type WorkspaceRecord = {title:string;meta:string;status:string;icon:IconName}

function actionDestination(title:string,current:Section):Section {
 const value=title.toLowerCase()
 if(value.includes('participant')||value.includes('profile'))return 'Participants'
 if(value.includes('indicator'))return 'MERL & indicators'
 if(value.includes('assessment')||value.includes('survey')||value.includes('instrument'))return 'Assessments'
 if(value.includes('cohort')||value.includes('training')||value.includes('attendance'))return 'Learning & cohorts'
 if(value.includes('indicator')||value.includes('data quality')||value.includes('verification')||value.includes('duplicate')||value.includes('merl'))return 'MERL & indicators'
 if(value.includes('enterprise')||value.includes('employment')||value.includes('outcome')||value.includes('job'))return 'Enterprise & jobs'
 if(value.includes('grant')||value.includes('asset')||value.includes('service')||value.includes('finance')||value.includes('market'))return 'Grants & services'
 if(value.includes('message')||value.includes('communication')||value.includes('sms')||value.includes('notification'))return 'Communications'
 if(value.includes('document')||value.includes('evidence')||value.includes('certificate'))return 'Documents'
 if(value.includes('map')||value.includes('location')||value.includes('coverage')||value.includes('gis'))return 'GIS & coverage'
 if(value.includes('report')||value.includes('export'))return 'Reports'
 if(value.includes('field')||value.includes('sync')||value.includes('enumerator'))return 'Field operations'
 if(value.includes('case')||value.includes('follow-up')||value.includes('overdue')||value.includes('milestone')||value.includes('referral'))return 'Case management'
 if(value.includes('access')||value.includes('admin')||value.includes('audit')||value.includes('backup')||value.includes('integration')||value.includes('security')||value.includes('system'))return 'Administration'
 return current
}

