function ParticipantsTable({rows,query,setQuery,totalCount,onExport,onAction}:{rows:ParticipantRecord[];query:string;setQuery:(v:string)=>void;totalCount:number;onExport:(selectedIds:string[])=>void;onAction:(s:string)=>void}){
 const [status,setStatus]=useState('All statuses');const [selectedIds,setSelectedIds]=useState<string[]>([]);const visibleRows=rows.filter(person=>status==='All statuses'||person.status===status);const allSelected=visibleRows.length>0&&visibleRows.every(person=>selectedIds.includes(person.id));function toggleRow(id:string){setSelectedIds(current=>current.includes(id)?current.filter(value=>value!==id):[...current,id])}function toggleVisible(){setSelectedIds(current=>allSelected?current.filter(id=>!visibleRows.some(person=>person.id===id)):[...new Set([...current,...visibleRows.map(person=>person.id)])])}return <><div className="participant-metrics"><div><span>Total registered</span><b>{totalCount.toLocaleString()}</b><small><i>↑ 12.8%</i> vs last quarter</small></div><div><span>Awaiting review</span><b>284</b><small>Across all countries</small></div><div><span>Profile complete</span><b>91.4%</b><small>+3.2 pts this month</small></div><div><span>Possible duplicates</span><b>36</b><small>Needs exception review</small></div></div><section className="panel participant-table-panel"><div className="table-toolbar"><div><h3>Participant directory</h3><p>Master records · identity and lifecycle status</p></div><div className="table-actions"><label className="search-field"><Icon name="search" size={16}/><input placeholder="Search name or ID..." value={query} onChange={e=>setQuery(e.target.value)}/><kbd>⌘ K</kbd></label><select value={status} onChange={e=>setStatus(e.target.value)}><option>All statuses</option><option>Active</option><option>Needs follow-up</option><option>Review needed</option></select><button className="button button-secondary" onClick={()=>onExport(selectedIds)}><Icon name="download" size={15}/>{selectedIds.length?`Export ${selectedIds.length} selected`:'Export filtered'}</button></div></div><div className="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="Select visible participants" checked={allSelected} onChange={toggleVisible}/></th><th>PARTICIPANT</th><th>LOCATION</th><th>PATHWAY</th><th>CURRENT STAGE</th><th>STATUS</th><th></th></tr></thead><tbody>{visibleRows.map(p=><tr key={p.id}><td><input type="checkbox" aria-label={`Select ${p.name}`} checked={selectedIds.includes(p.id)} onChange={()=>toggleRow(p.id)}/></td><td><button className="person-cell" onClick={()=>onAction(`Participant · ${p.name}`)}><span className="avatar avatar-person">{p.initials}</span><span><b>{p.name}</b><small>{p.id}</small></span></button></td><td>{p.location}</td><td><span className="path-tag">{p.path}</span></td><td>{p.stage}</td><td><span className={`table-status ${p.status==='Active'?'active-status':p.status==='Needs follow-up'?'follow-status':'review-status'}`}><i></i>{p.status}</span></td><td><button className="icon-button" onClick={()=>onAction(`Participant · ${p.name}`)} aria-label={`Open ${p.name}`}><Icon name="dots" size={17}/></button></td></tr>)}</tbody></table></div><div className="table-bottom"><span>Showing <b>{visibleRows.length}</b> {totalCount.toLocaleString()} total records</span><span className="sample-pagination">Showing the local prototype sample; full dataset is not connected.</span></div></section><div className="module-note"><Icon name="shield" size={15}/><span><b>Privacy by design.</b> Sensitive inclusion fields and identity evidence are restricted by role and geography. Every view and export is audit logged.</span><button onClick={()=>onAction('Access policy')}>Access policy <Icon name="arrow" size={13}/></button></div></>}

